  "check_code": "import sqlite3
from pathlib import Path


TARGET_PACKAGE_ID = "EP-Q3-2025-016"
TARGET_ANCHOR_ID = "SP-ANCHOR-Q3-016"
TARGET_VERSION = "v2"
TARGET_APPROVAL_EVENT_ID = "SP-APP-Q3-016"
TARGET_APPROVER_ID = "USR-SEC-0003"

BASELINE_Q3_STATUSES = {
    **{f"EP-Q3-2025-{number:03d}": "Approved" for number in range(1, 16)},
    **{f"EP-Q3-2025-{number:03d}": "Pending" for number in range(16, 20)},
}


def _db_path(ws, system_name):
    candidates = [
        Path(ws).parent / "system" / system_name / "state.db",
        Path.cwd() / "system" / system_name / "state.db",
    ]
    for candidate in candidates:
        if candidate.exists():
            return candidate
    raise FileNotFoundError(f"{system_name} state.db not found")


def _connect(ws, system_name):
    connection = sqlite3.connect(_db_path(ws, system_name))
    connection.row_factory = sqlite3.Row
    return connection


def _table_exists(connection, table_name):
    return connection.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",
        (table_name,),
    ).fetchone() is not None


def check_manager_approval_recorded(ws):
    with _connect(ws, "rsa_archer_compliance") as connection:
        package = connection.execute(
            """SELECT package_id, readiness_status, manager_approval_status,
                      sharepoint_anchor_id, sharepoint_version, approval_event_id
               FROM evidence_packages WHERE package_id=?""",
            (TARGET_PACKAGE_ID,),
        ).fetchone()
        if package is None:
            return {"score": 0, "detail": "Target evidence package is missing."}
        expected_package = {
            "package_id": TARGET_PACKAGE_ID,
            "readiness_status": "Complete",
            "manager_approval_status": "Approved",
            "sharepoint_anchor_id": TARGET_ANCHOR_ID,
            "sharepoint_version": TARGET_VERSION,
            "approval_event_id": TARGET_APPROVAL_EVENT_ID,
        }
        if dict(package) != expected_package:
            return {"score": 0, "detail": f"Target package state is incorrect: {dict(package)}"}
        if not _table_exists(connection, "manager_approval_history"):
            return {"score": 0, "detail": "Manager approval history was not recorded."}
        rows = connection.execute(
            """SELECT action, approver_user_id, approval_event_id, decision_note
               FROM manager_approval_history WHERE package_id=?""",
            (TARGET_PACKAGE_ID,),
        ).fetchall()
        if len(rows) != 1:
            return {"score": 0, "detail": f"Expected one target approval history row, found {len(rows)}."}
        history = dict(rows[0])
        if history["action"] != "Approved":
            return {"score": 0, "detail": "The recorded manager action is not Approved."}
        if history["approver_user_id"] != TARGET_APPROVER_ID:
            return {"score": 0, "detail": "The approval used the wrong executive identity."}
        if history["approval_event_id"] != TARGET_APPROVAL_EVENT_ID:
            return {"score": 0, "detail": "The approval did not reuse the package's existing event reference."}
        if not str(history["decision_note"] or "").strip():
            return {"score": 0, "detail": "The approval history lacks a decision note."}
    return {"score": 1, "detail": "Target approval and audit history are correct."}


def check_archer_scope_integrity(ws):
    with _connect(ws, "rsa_archer_compliance") as connection:
        rows = connection.execute(
            """SELECT package_id, manager_approval_status, sharepoint_anchor_id,
                      sharepoint_version, approval_event_id
               FROM evidence_packages WHERE package_period='2025-Q3'
               ORDER BY package_id"""
        ).fetchall()
        if {row["package_id"] for row in rows} != set(BASELINE_Q3_STATUSES):
            return {"score": 0, "detail": "The Q3 package population changed."}
        for row in rows:
            expected_status = "Approved" if row["package_id"] == TARGET_PACKAGE_ID else BASELINE_Q3_STATUSES[row["package_id"]]
            if row["manager_approval_status"] != expected_status:
                return {"score": 0, "detail": f"Unexpected status change for {row['package_id']}."}
            if row["package_id"] == TARGET_PACKAGE_ID and (
                row["sharepoint_anchor_id"] != TARGET_ANCHOR_ID
                or row["sharepoint_version"] != TARGET_VERSION
                or row["approval_event_id"] != TARGET_APPROVAL_EVENT_ID
            ):
                return {"score": 0, "detail": "The selected package's SharePoint linkage changed."}
        if _table_exists(connection, "manager_approval_history"):
            other_count = connection.execute(
                "SELECT COUNT(*) FROM manager_approval_history WHERE package_id<>?",
                (TARGET_PACKAGE_ID,),
            ).fetchone()[0]
            if other_count:
                return {"score": 0, "detail": "Approval history was added for another package."}
    return {"score": 1, "detail": "Archer changes are limited to the authorized package."}


def check_sharepoint_scope_integrity(ws):
    expected_counts = {
        "workspace_documents": 17,
        "document_versions": 31,
        "document_anchors": 134,
        "approval_events": 27,
    }
    with _connect(ws, "microsoft_sharepoint_compliance") as connection:
        for table_name, expected_count in expected_counts.items():
            actual_count = connection.execute(f"SELECT COUNT(*) FROM {table_name}").fetchone()[0]
            if actual_count != expected_count:
                return {"score": 0, "detail": f"SharePoint {table_name} count changed."}
        q3_records = connection.execute(
            """SELECT
                 (SELECT COUNT(*) FROM workspace_documents WHERE review_period IN ('2025-Q3','Q3 FY2025','FY2025-Q3'))
               + (SELECT COUNT(*) FROM document_anchors WHERE anchor_id LIKE 'SP-ANCHOR-Q3-%' OR source_record_id LIKE 'EP-Q3-2025-%')
               + (SELECT COUNT(*) FROM approval_events WHERE approval_event_id LIKE 'SP-APP-Q3-%')"""
        ).fetchone()[0]
        if q3_records != 0:
            return {"score": 0, "detail": "Invented Q3 records were added to SharePoint Compliance."}
    return {"score": 1, "detail": "SharePoint Compliance remains unchanged."}
